        s.line(X(0), 5.42, X(22), 5.42, { color: "muted", w: 1 });
        [0, 5, 10, 15, 20].forEach(v => s.text(X(v) - 0.5, 5.5, 1.0, 0.36, `${v}`, { font: "cond", size: 16, color: "muted", align: "center" }));
        s.text(X(22) - 3.5, 5.5, 3.5, 0.36, "Top speed, mph →", { font: "light", size: 15, color: "muted", align: "right" });
